  if (
    sourceTextOffsetStatus(normalized, sourceText.length) !==
      SOURCE_TEXT_OFFSET_OK
  ) {
    throw new Error("Source text offset out of bounds.");
  }
  return sourceText.source.charCodeAt(normalized) >>> 0;
